insert into public.controls
(id,framework,framework_code,sno,sub_area,control_objective,risk,key_control,control_description,assertions,manual_automated,frequency,control_type,requires_request,request_type)
select id,framework,"frameworkCode",sno,"subArea","controlObjective",risk,"keyControl","controlDescription",assertions,"manualAutomated",frequency,"controlType","requiresRequest","requestType"
from jsonb_to_recordset('[{"id": "FSCR-01", "framework": "Financial Statement Closing & Reporting", "frameworkCode": "FSCR", "sno": 1, "subArea": "Chart of account management", "controlObjective": "To ensure that appropriate ledger are created, properly mapped in the financial statements & unused or duplicate ledger are deactivated in the system.", "risk": "- Inappropriate ledger created - Duplicate ledger created - Incorrect grouping of GL code in the Tally", "keyControl": false, "controlDescription": "- A check is done by the creator whether new ledger is to be created or existing ledger can be used. - If new ledger is required then it is created in the appropriate head and grouping by the finance team. - At the time of ledger creation verbal approval is obtained from finance head and at the end of the financial year approval is obtained for all the ledgers created during the period.", "assertions": {"cutoff": "X", "accuracy": "P", "completeness": "P", "existenceOccurrence": "X", "rightsObligations": "X", "valuationAllocation": "P", "presentationDisclosure": "P"}, "manualAutomated": "Manual", "frequency": "As and When", "controlType": "Preventive", "requiresRequest": true, "requestType": "ledger"}, {"id": "FSCR-02", "framework": "Financial Statement Closing & Reporting", "frameworkCode": "FSCR", "sno": 2, "subArea": "Expense accounting", "controlObjective": "Journal entries are reviewed and accounted for accurately and completely in the correct period and no unauthorized entries are posted in financial books once the books are closed.", "risk": "- Improper, inaccurate or incomplete journal entries passed - Journal entries missed to be posted in the system or Journal entries recorded in incorrect period leading to incorrect financial books.", "keyControl": true, "controlDescription": "- All journal entries are reviewed - A month end review/variance analysis is done by Finance Head by reviewing MIS of the month", "assertions": {"cutoff": "P", "accuracy": "P", "completeness": "P", "existenceOccurrence": "P", "rightsObligations": "X", "valuationAllocation": "P", "presentationDisclosure": "P"}, "manualAutomated": "Manual", "frequency": "As and When", "controlType": "Preventive", "requiresRequest": true, "requestType": "generic"}, {"id": "FSCR-03", "framework": "Financial Statement Closing & Reporting", "frameworkCode": "FSCR", "sno": 3, "subArea": "Provisioning", "controlObjective": "Expenses are booked against provision created in books and no unrequired amount of provision is carried out in books of accounts.", "risk": "- Expenses not provided for - Incorrect provision carried forward for long time.", "keyControl": false, "controlDescription": "- Provisions created at month end are reversed and then expenses are booked as and when approved invoice for the same is received. - Provisions created at year end are carried over in books which are approved by the requisite authority. - On monthly basis, Finance team maintains a tracker for all recurring expenses and the same are provided for every month.", "assertions": {"cutoff": "P", "accuracy": "P", "completeness": "P", "existenceOccurrence": "P", "rightsObligations": "P", "valuationAllocation": "P", "presentationDisclosure": "P"}, "manualAutomated": "Manual", "frequency": "As and When", "controlType": "Preventive", "requiresRequest": true, "requestType": "generic"}, {"id": "FSCR-04", "framework": "Financial Statement Closing & Reporting", "frameworkCode": "FSCR", "sno": 4, "subArea": "Write off''s", "controlObjective": "All write offs are authorized and recorded accurately within the appropriate accounting period", "risk": "Write-offs not recorded/not authorized resulting in over/ under valuation of assets/ liabilities.", "keyControl": false, "controlDescription": "- Details of long overdue/doubtful recoverable / payable items are prepared by the accounts team and shared with Finance Head/Senior finance manager for review. - Necessary follow-ups are ensured by the accounting and finance team. - After reasonable assessment and obtaining necessary approval from Finance Head, debtors / creditors are written off from the books.", "assertions": {"cutoff": "P", "accuracy": "P", "completeness": "P", "existenceOccurrence": "P", "rightsObligations": "P", "valuationAllocation": "P", "presentationDisclosure": "P"}, "manualAutomated": "Manual", "frequency": "As and When", "controlType": "Preventive", "requiresRequest": true, "requestType": "generic"}, {"id": "FSCR-05", "framework": "Financial Statement Closing & Reporting", "frameworkCode": "FSCR", "sno": 5, "subArea": "Trial balance and ledger monitoring", "controlObjective": "To ensure that the Opening balance ties to the previous year''s closing balance/signed audited financial statements", "risk": "Opening balance does not tie to the previous year''s closing balance/signed audited financial statements", "keyControl": false, "controlDescription": "The opening balances are compared with the closing balances of the previous year''s audited financials by finance team and appropriately signed off.", "assertions": {"cutoff": "X", "accuracy": "P", "completeness": "P", "existenceOccurrence": "P", "rightsObligations": "P", "valuationAllocation": "P", "presentationDisclosure": "P"}, "manualAutomated": "Manual", "frequency": "Monthly", "controlType": "Preventive", "requiresRequest": false, "requestType": "generic"}, {"id": "FSCR-06", "framework": "Financial Statement Closing & Reporting", "frameworkCode": "FSCR", "sno": 6, "subArea": "Trial balance and ledger monitoring", "controlObjective": "To ensure that no entries are passed after closure of accounting period", "risk": "Entry is passed even after closure of accounting period", "keyControl": false, "controlDescription": "The rights of opening and closure of accounting period in system is restricted to selective employees of Finance team.", "assertions": {"cutoff": "P", "accuracy": "P", "completeness": "P", "existenceOccurrence": "P", "rightsObligations": "X", "valuationAllocation": "P", "presentationDisclosure": "P"}, "manualAutomated": "Manual", "frequency": "Monthly", "controlType": "Preventive", "requiresRequest": false, "requestType": "generic"}, {"id": "FSCR-07", "framework": "Financial Statement Closing & Reporting", "frameworkCode": "FSCR", "sno": 7, "subArea": "Financial Statement Closure", "controlObjective": "To ensure compliance with RBI/MCA/Accounting Standards requirement", "risk": "The annual financial statements are not prepared in line with required regulatory format.", "keyControl": true, "controlDescription": "- Applicability of any new regulatory update is evaluated and discussed with the relevent experts. - The Finance Controller refers to the amendments and the latest circulars published by RBI/MCA/ICAI/Accounting Standards and evaluates whether there are any changes that need to be incorporated in the format of the financial statements.", "assertions": {"cutoff": "P", "accuracy": "P", "completeness": "P", "existenceOccurrence": "P", "rightsObligations": "P", "valuationAllocation": "P", "presentationDisclosure": "P"}, "manualAutomated": "Manual", "frequency": "Annually and whenever there is a significant transaction or change in an accounting policy", "controlType": "Preventive", "requiresRequest": false, "requestType": "generic"}, {"id": "FSCR-08", "framework": "Financial Statement Closing & Reporting", "frameworkCode": "FSCR", "sno": 8, "subArea": "Financial Statement Closure", "controlObjective": "To ensure the disclosure of required accounting policies", "risk": "The accounting policies as disclosed in the Financial statements does not include all applicable accounting policies as followed by the Company. Also the critical accounting policies not disclosed as such.", "keyControl": false, "controlDescription": "All policies are prepared and disclosed by the Finance Controller and reviewed by the Finance Head.", "assertions": {"cutoff": "X", "accuracy": "P", "completeness": "P", "existenceOccurrence": "X", "rightsObligations": "X", "valuationAllocation": "P", "presentationDisclosure": "P"}, "manualAutomated": "Manual", "frequency": "Annually and whenever there is a significant transaction or change in an accounting policy", "controlType": "Preventive", "requiresRequest": false, "requestType": "generic"}, {"id": "FSCR-09", "framework": "Financial Statement Closing & Reporting", "frameworkCode": "FSCR", "sno": 9, "subArea": "Financial Statement Closure", "controlObjective": "Disclosure of all related party transactions", "risk": "All related party transactions are not correctly identified and accurately disclosed for the disclosure purpose.", "keyControl": true, "controlDescription": "- All related parties are identified by financial controller in accordance with AS 18. - The transactions with such parties are evaluated from an arm''s length perspective. - The list of related parties, closing balances and the transactions during the year are disclosed in the financial statements.", "assertions": {"cutoff": "P", "accuracy": "P", "completeness": "P", "existenceOccurrence": "P", "rightsObligations": "P", "valuationAllocation": "P", "presentationDisclosure": "P"}, "manualAutomated": "Manual", "frequency": "Annually", "controlType": "Detective", "requiresRequest": false, "requestType": "generic"}, {"id": "FSCR-10", "framework": "Financial Statement Closing & Reporting", "frameworkCode": "FSCR", "sno": 10, "subArea": "Financial Statement Closure", "controlObjective": "Ensure accurate classification of entries", "risk": "Review of financial statement to ensure true and correct books of accounts", "keyControl": true, "controlDescription": "The finance Controller review the financial statement to ensure the proper classification and presentation of the same.", "assertions": {"cutoff": "P", "accuracy": "P", "completeness": "P", "existenceOccurrence": "P", "rightsObligations": "P", "valuationAllocation": "P", "presentationDisclosure": "P"}, "manualAutomated": "Manual", "frequency": "Annually", "controlType": "Detective", "requiresRequest": false, "requestType": "generic"}, {"id": "FA-01", "framework": "Fixed Assets", "frameworkCode": "FA", "sno": 1, "subArea": "Fixed Assets- Acquisition", "controlObjective": "To ensure that capital expenditure is properly authorized and approved in accordance with the Company''s Delegation of Authority (DOA) before procurement.", "risk": "Unauthorized or inappropriate acquisition of fixed assets, resulting in unapproved capital expenditure and potential financial loss.", "keyControl": true, "controlDescription": "All capital expenditure (CapEx) requests are reviewed and approved in accordance with the Company''s Delegation of Authority (DOA)/Authority Matrix before the purchase order is issued or procurement is initiated. Supporting documents, including the approved CapEx request, vendor quotation, and purchase order, are retained for audit purposes.", "assertions": {"cutoff": "P", "accuracy": "P", "completeness": "P", "existenceOccurrence": "P", "rightsObligations": "P", "valuationAllocation": "P", "presentationDisclosure": "P"}, "manualAutomated": "Manual", "frequency": "As and When", "controlType": "Preventive", "requiresRequest": true, "requestType": "generic"}, {"id": "FA-02", "framework": "Fixed Assets", "frameworkCode": "FA", "sno": 2, "subArea": "Fixed Assets - Depreciation", "controlObjective": "To ensure depreciation is calculated and recorded accurately in accordance with the Company''s accounting policy and applicable IGAAP requirements.", "risk": "Depreciation expense may be incorrectly calculated or recorded, resulting in misstatement of the carrying value of fixed assets and depreciation expense.", "keyControl": true, "controlDescription": "On a monthly basis, the Finance team calculates depreciation based on the approved fixed asset register, useful lives, residual values, and depreciation rates as per the Company''s accounting policy and the applicable provisions of the Companies Act, 2013/IGAAP. The depreciation workings are reviewed by the Finance Manager/Finance Controller before the journal entry is posted in the accounting system (Tally).", "assertions": {"cutoff": "P", "accuracy": "P", "completeness": "P", "existenceOccurrence": "P", "rightsObligations": "X", "valuationAllocation": "P", "presentationDisclosure": "P"}, "manualAutomated": "Manual", "frequency": "Monthly", "controlType": "Preventive", "requiresRequest": true, "requestType": "generic"}, {"id": "FA-03", "framework": "Fixed Assets", "frameworkCode": "FA", "sno": 3, "subArea": "Fixed Assets - review", "controlObjective": "To ensure that the Fixed Asset Register (FAR) is complete, accurate, and updated for all asset movements.", "risk": "Fixed asset additions, disposals, depreciation, or other changes may not be recorded accurately or completely, resulting in misstatement of fixed assets and depreciation.", "keyControl": true, "controlDescription": "On a monthly basis, the Finance team reviews the Fixed Asset Register (FAR) and reconciles it with the general ledger to verify that all asset additions, disposals, transfers, depreciation, and other asset-related transactions have been accurately recorded and updated. Any discrepancies identified are investigated and resolved after obtaining appropriate approvals.", "assertions": {"cutoff": "P", "accuracy": "P", "completeness": "P", "existenceOccurrence": "P", "rightsObligations": "P", "valuationAllocation": "P", "presentationDisclosure": "P"}, "manualAutomated": "Manual", "frequency": "As and When", "controlType": "Detective", "requiresRequest": true, "requestType": "generic"}, {"id": "FA-04", "framework": "Fixed Assets", "frameworkCode": "FA", "sno": 4, "subArea": "Safeguarding of Assets", "controlObjective": "To ensure all fixed assets are uniquely identified and adequately safeguarded through proper asset tagging.", "risk": "Fixed assets may not be properly identified or tracked due to inadequate or missing asset tags, leading to risk of loss, misappropriation, duplication, or inaccurate asset records.", "keyControl": true, "controlDescription": "Upon receipt and capitalization of a fixed asset, the Administration team generates and affixes a unique asset tag to the asset. The asset tag details are shared with the Finance team for updating the Fixed Asset Register (FAR), ensuring each asset is uniquely identifiable and can be tracked throughout its useful life.", "assertions": {"cutoff": "X", "accuracy": "P", "completeness": "P", "existenceOccurrence": "P", "rightsObligations": "P", "valuationAllocation": "X", "presentationDisclosure": "X"}, "manualAutomated": "Manual", "frequency": "As and When", "controlType": "Preventive", "requiresRequest": false, "requestType": "generic"}, {"id": "FA-05", "framework": "Fixed Assets", "frameworkCode": "FA", "sno": 5, "subArea": "Fixed Assets – Physical Verification", "controlObjective": "To ensure the existence, completeness, and safeguarding of fixed assets through periodic physical verification.", "risk": "Fixed assets recorded in the Fixed Asset Register (FAR) may not physically exist, or unrecorded, missing, damaged, or obsolete assets may not be identified, resulting in inaccurate financial reporting.", "keyControl": true, "controlDescription": "The Company conducts physical verification of fixed assets at least once every three years, with selected asset categories verified annually or at such intervals as determined by management. The results of the physical verification are reconciled with the Fixed Asset Register (FAR), and any discrepancies identified (such as missing, damaged, obsolete, or unrecorded assets) are investigated, approved by the appropriate authority, and updated in the books of account where necessary.", "assertions": {"cutoff": "X", "accuracy": "P", "completeness": "P", "existenceOccurrence": "P", "rightsObligations": "P", "valuationAllocation": "P", "presentationDisclosure": "P"}, "manualAutomated": "Manual", "frequency": "Annually (or on a rotational basis ensuring all assets are verified at least once in every three years).", "controlType": "Detective", "requiresRequest": true, "requestType": "generic"}, {"id": "FA-06", "framework": "Fixed Assets", "frameworkCode": "FA", "sno": 6, "subArea": "Capitalization of Assets", "controlObjective": "To ensure only eligible expenditure is capitalized", "risk": "Revenue expenditure may be incorrectly capitalized or capital expenditure may be expensed.", "keyControl": true, "controlDescription": "Finance reviews all capital expenditure invoices against the Company''s capitalization policy and AS 10 before capitalization. Expenditure not meeting capitalization criteria or below the capitalization threshold is charged to the Statement of Profit and Loss.", "assertions": {"cutoff": "X", "accuracy": "P", "completeness": "P", "existenceOccurrence": "P", "rightsObligations": "X", "valuationAllocation": "P", "presentationDisclosure": "P"}, "manualAutomated": "Manual", "frequency": "As and when incurred", "controlType": "Preventive", "requiresRequest": false, "requestType": "generic"}, {"id": "FA-07", "framework": "Fixed Assets", "frameworkCode": "FA", "sno": 7, "subArea": "Fixed Asset Disposal / Write-off", "controlObjective": "To ensure disposals and write-offs are properly authorized and recorded", "risk": "Disposed or scrapped assets may continue to remain in the books or gain/loss may be incorrectly recorded.", "keyControl": true, "controlDescription": "All disposals, scrapping and write-offs require approval as per the Delegation of Authority. Finance updates the FAR, records gain/loss on disposal and retains supporting documents.", "assertions": {"cutoff": "✓", "accuracy": "✓", "completeness": "✓", "existenceOccurrence": "✓", "rightsObligations": "✓", "valuationAllocation": "✓", "presentationDisclosure": "✓"}, "manualAutomated": "Manual", "frequency": "As and when required", "controlType": "Preventive", "requiresRequest": true, "requestType": "generic"}, {"id": "FA-08", "framework": "Fixed Assets", "frameworkCode": "FA", "sno": 8, "subArea": "FAR vs General Ledger Reconciliation", "controlObjective": "To ensure the Fixed Asset Register agrees with the General Ledger", "risk": "Differences between the FAR and General Ledger may result in inaccurate financial reporting.", "keyControl": true, "controlDescription": "Finance performs a monthly reconciliation between the Fixed Asset Register and the General Ledger. Any differences are investigated, resolved and approved.", "assertions": {"cutoff": "X", "accuracy": "P", "completeness": "P", "existenceOccurrence": "P", "rightsObligations": "P", "valuationAllocation": "P", "presentationDisclosure": "P"}, "manualAutomated": "Manual", "frequency": "Monthly", "controlType": "Detective", "requiresRequest": true, "requestType": "generic"}, {"id": "FA-09", "framework": "Fixed Assets", "frameworkCode": "FA", "sno": 9, "subArea": "Impairment / Obsolescence Review", "controlObjective": "To ensure assets are carried at appropriate values", "risk": "Impaired, obsolete or damaged assets may be overstated.", "keyControl": true, "controlDescription": "Management performs an annual review for impairment indicators. Where impairment exists, necessary accounting adjustments are recorded in accordance with applicable accounting standards.", "assertions": {"cutoff": "X", "accuracy": "P", "completeness": "X", "existenceOccurrence": "P", "rightsObligations": "X", "valuationAllocation": "P", "presentationDisclosure": "P"}, "manualAutomated": "Manual", "frequency": "Annually", "controlType": "Detective", "requiresRequest": false, "requestType": "generic"}, {"id": "P2P-01", "framework": "Procure to Pay", "frameworkCode": "P2P", "sno": 1, "subArea": "Vendor selection", "controlObjective": "To ensure that all vendors are appropriately evaluated, reviewed, and approved before engagement.", "risk": "Engagement of illegitimate, dishonest, prohibited, or unsuitable vendors may result in financial loss, legal or regulatory penalties, operational disruption, and reputational damage.", "keyControl": true, "controlDescription": "- Required services are in consultation with the respective department head and after obtaining finance head approval, vendor is selected.", "assertions": {"cutoff": "X", "accuracy": "P", "completeness": "P", "existenceOccurrence": "P", "rightsObligations": "X", "valuationAllocation": "X", "presentationDisclosure": "X"}, "manualAutomated": "Manual", "frequency": "As and When", "controlType": "Preventive", "requiresRequest": true, "requestType": "generic"}, {"id": "P2P-02", "framework": "Procure to Pay", "frameworkCode": "P2P", "sno": 2, "subArea": "Vendor Selection and Empanelment", "controlObjective": "To ensure that vendors are empanelled only after completion of appropriate due diligence and obtaining the required approvals.", "risk": "Procurement from unempanelled, fictitious, unauthorised, or non-compliant vendors may result in fraudulent payments, financial loss, statutory non-compliance, and reputational damage.", "keyControl": true, "controlDescription": "- AP team obtained supporting documents to check KYC . Vendor is empanelled after KYC verification like GST, MSME status, PAN and Cancel cheque etc. as per applicibility.", "assertions": {"cutoff": "X", "accuracy": "P", "completeness": "P", "existenceOccurrence": "P", "rightsObligations": "P", "valuationAllocation": "X", "presentationDisclosure": "X"}, "manualAutomated": "Manual", "frequency": "As and When", "controlType": "Preventive", "requiresRequest": true, "requestType": "generic"}, {"id": "P2P-03", "framework": "Procure to Pay", "frameworkCode": "P2P", "sno": 3, "subArea": "Vendor master management", "controlObjective": "To ensure that complete, accurate, and valid documents are obtained before creating or modifying a vendor master; access is restricted to authorised personnel; and adequate segregation of duties is maintained.", "risk": "Invalid, inaccurate, or incomplete supporting documents may be accepted. Unauthorised or incorrect creation or modification of vendor records, including bank details, may result in duplicate or fictitious vendors, fraudulent or erroneous payments, statutory non-compliance, and financial loss. Inadequate segregation between initiation, review, and approval may allow unauthorised changes to remain undetected.", "keyControl": true, "controlDescription": "- Vendor master in system is checked thoroughly before creation of the vendor in the system. - Vendors creation and modifications rights in system are restricted to Finance team for each vendor. - Supporting documents submitted by the vendor are validated by Finance team for accuracy & completeness. - In case mandatory documents are not available, AP team coordinates to get such documents from vendor. - Finance Head checks the same before releasing the payment", "assertions": {"cutoff": "X", "accuracy": "P", "completeness": "P", "existenceOccurrence": "P", "rightsObligations": "P", "valuationAllocation": "X", "presentationDisclosure": "X"}, "manualAutomated": "Manual", "frequency": "As and When", "controlType": "Preventive", "requiresRequest": true, "requestType": "generic"}, {"id": "P2P-04", "framework": "Procure to Pay", "frameworkCode": "P2P", "sno": 4, "subArea": "Agreement/PO with vendors", "controlObjective": "To ensure that vendor charges are consistent with the approved commercial terms and that all vendor engagements are supported by valid, duly authorised, and legally enforceable agreements or purchase orders.", "risk": "Vendors may charge incorrect or unauthorised rates, resulting in excess payments and financial loss. Agreements may contain unfavourable or incomplete terms or may expire without timely renewal, leading to disputes, service disruption, non-compliance, or difficulty in enforcing the Company’s contractual rights.", "keyControl": true, "controlDescription": "Before commencement of services, vendor agreements or PO are reviewed and approved by the respective Department Head and Finance team. The agreements specify the scope, rates, payment terms, validity period, and other key conditions. Vendor invoices are verified against the valid agreement or PO before payment, and renewals are tracked to prevent agreements from expiring.", "assertions": {"cutoff": "P", "accuracy": "P", "completeness": "P", "existenceOccurrence": "P", "rightsObligations": "P", "valuationAllocation": "P", "presentationDisclosure": "X"}, "manualAutomated": "Manual", "frequency": "As and When", "controlType": "Preventive", "requiresRequest": true, "requestType": "generic"}, {"id": "P2P-05", "framework": "Procure to Pay", "frameworkCode": "P2P", "sno": 5, "subArea": "Invoice Processing", "controlObjective": "To ensure that vendor invoices are valid, accurate, complete and supported by evidence of receipt of services.", "risk": "Inadequate verification may result in the processing of fictitious, duplicate, inaccurate or unsupported invoices, leading to fraud, excess payment or financial loss.", "keyControl": true, "controlDescription": "Before processing an invoice, the AP team obtains confirmation of receipt of services from the concerned department and verifies the invoice against the applicable agreement/PO, approved rates, service period and supporting documents. The AP team also checks the invoice for arithmetical accuracy, duplicate booking, applicable GST and TDS, and obtains the required approval as per the authority matrix before recording and processing it for payment.", "assertions": {"cutoff": "P", "accuracy": "P", "completeness": "P", "existenceOccurrence": "P", "rightsObligations": "P", "valuationAllocation": "P", "presentationDisclosure": "P"}, "manualAutomated": "Manual", "frequency": "As and When", "controlType": "Preventive", "requiresRequest": true, "requestType": "generic"}, {"id": "P2P-06", "framework": "Procure to Pay", "frameworkCode": "P2P", "sno": 6, "subArea": "Payment to vendor", "controlObjective": "To ensure that payments are made accurately, only for services actually received, to the correct vendor and after obtaining the required approvals.", "risk": "Payments may be made for services not received, for incorrect or duplicate amounts, or to an unauthorised vendor or bank account, resulting in fraud or financial loss.", "keyControl": true, "controlDescription": "After obtaining approval from respective depatment and the same is reviewed by Senior Finance Manager or Finance head for further processing for payment to Vendors.", "assertions": {"cutoff": "P", "accuracy": "P", "completeness": "P", "existenceOccurrence": "P", "rightsObligations": "P", "valuationAllocation": "P", "presentationDisclosure": "X"}, "manualAutomated": "Manual", "frequency": "As and When", "controlType": "Preventive", "requiresRequest": true, "requestType": "generic"}, {"id": "P2P-07", "framework": "Procure to Pay", "frameworkCode": "P2P", "sno": 7, "subArea": "Payment to gig workers", "controlObjective": "Correct payment made to gig workers for the service rendered.", "risk": "- Payment to gig workers for services not rendered. - Incorrect payment made to Gig worker", "keyControl": true, "controlDescription": "All tasks completed by the gig worker, are reviewed by the ops team and customer. Post approval of the task, the fees for the approved task is available to be withdrawn by the gig worker.", "assertions": {"cutoff": "P", "accuracy": "P", "completeness": "P", "existenceOccurrence": "P", "rightsObligations": "P", "valuationAllocation": "P", "presentationDisclosure": "X"}, "manualAutomated": "Manual", "frequency": "As and When", "controlType": "Preventive", "requiresRequest": true, "requestType": "generic"}, {"id": "P2P-08", "framework": "Procure to Pay", "frameworkCode": "P2P", "sno": 8, "subArea": "Vendor reconciliation", "controlObjective": "Ensure that periodically, accounts are reconciled with the vendors.", "risk": "Absence of vendor balance review leading to incorrect reporting of balances at period end or old pending balances for significant period", "keyControl": true, "controlDescription": "In case of any difference/dispute, a reconciliation is prepared by Finance and also obtained ledger/statement from vendor if required..", "assertions": {"cutoff": "P", "accuracy": "P", "completeness": "P", "existenceOccurrence": "P", "rightsObligations": "P", "valuationAllocation": "P", "presentationDisclosure": "P"}, "manualAutomated": "Manual", "frequency": "As and When", "controlType": "Detective", "requiresRequest": false, "requestType": "generic"}, {"id": "R2R-01", "framework": "Record to Report", "frameworkCode": "R2R", "sno": 1, "subArea": "Customer Master Creation", "controlObjective": "Authorized Customer Masters are created in System", "risk": "Unauthorized Customer Masters may be created in system", "keyControl": false, "controlDescription": "Customer master records are created in the system only upon receipt of an approved Work Order (WO), Purchase Order (PO), or duly executed customer agreement. The Finance/AR team verifies the supporting documents prior to master creation. No project/service activation is permitted without a valid PO or signed agreement.", "assertions": {"cutoff": "X", "accuracy": "P", "completeness": "P", "existenceOccurrence": "P", "rightsObligations": "X", "valuationAllocation": "X", "presentationDisclosure": "X"}, "manualAutomated": "Manual", "frequency": "As & When required", "controlType": "Preventive Control", "requiresRequest": true, "requestType": "generic"}, {"id": "R2R-02", "framework": "Record to Report", "frameworkCode": "R2R", "sno": 2, "subArea": "Customer Credit Approval", "controlObjective": "To ensure customer credit terms are approved as per the company''s credit policy and to minimize credit risk", "risk": "Inappropriate credit periods may be granted without proper approval, resulting in delayed collections, increased working capital requirements, and potential bad debts", "keyControl": true, "